"""Self-contained Persian report with every result and explicit selection tiers."""
from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'high_cagr/output'
def fmt(x):return '—' if x is None else f'{x:,.2f}'
def metrics(r):
 return ''.join(f'<td>{fmt(r[k])}</td>' for k in ['cagr_pct','return_pct','profit_factor','max_dd_pct','net_profit'])
def main():
 m=json.loads((OUT/'matrix.json').read_text());w=m['winner'];rows=[]
 for index,r in enumerate(m['matrix'],1):
  desc=f"{r['universe']} | {r['preset']} | {r['entry_timeframe']} N{r['lookback']} | {r['trail']} | PY{int(r['pyramid'])} | R{r['risk']*100:g}% | {r['max_open_positions']} slots"
  rows.append(f'<tr data-tier="{r["dd_tier"] or 99}" data-positive="{int(r["positive_periods"])}" data-universe="{r["universe"]}"><td>{index}</td><td dir="ltr">{html.escape(desc)}</td><td>{r["dd_tier"] or "رد"}</td>'+metrics(r['full'])+metrics(r['train'])+metrics(r['oos'])+f'<td>{r["full"]["root_entries"]}</td><td>{r["full"]["pyramid_adds"]}</td><td>{fmt(r["full"]["fees"])}</td><td>{fmt(r["full"]["funding_pnl"])}</td><td>{fmt(r["full"]["avg_margin_pct"])}</td></tr>')
 tiers=''
 for limit in [25,30,35]:
  r=m['tier_winners'][str(limit)]
  tiers+=f'<article><h3>سقف DD {limit}٪ در هر سه دوره</h3>'+('هیچ ترکیبی واجد شرایط نشد.' if not r else f'<p dir="ltr">{r["id"]}</p><b>CAGR {fmt(r["full"]["cagr_pct"])}٪</b><p>DD کل {fmt(r["full"]["max_dd_pct"])}٪؛ DD بدترین دوره {fmt(r["worst_period_dd_pct"])}٪</p>')+'</article>'
 winner='هیچ برنده‌ای زیر سقف ۳۵٪ وجود ندارد؛ تنظیمات ربات حفظ شدند.'
 breakdown=''
 if w:
  winner=f'<p dir="ltr">{w["id"]}</p><p>CAGR کل: <b>{fmt(w["full"]["cagr_pct"])}٪</b>؛ سود خالص: <b>${fmt(w["full"]["net_profit"])}</b>؛ افت کل: <b>{fmt(w["full"]["max_dd_pct"])}٪</b>؛ افت بدترین دوره: {fmt(w["worst_period_dd_pct"])}٪</p><p>ورود پایه: {w["full"]["root_entries"]}؛ افزودن به برنده: {w["full"]["pyramid_adds"]}؛ متوسط مارجین درگیر: {fmt(w["full"]["avg_margin_pct"])}٪</p>'
  breakdown='<h2>تفکیک سود برنده ($)</h2><table><thead><tr><th>نماد</th><th>کل</th><th>Train</th><th>۲۰۲۵–۲۰۲۶</th></tr></thead><tbody>'+''.join('<tr><td>'+s+'</td>'+''.join('<td>'+fmt(w[p]['per_symbol'][s]['net_profit'])+'</td>' for p in ['full','train','oos'])+'</tr>' for s in w['symbols'])+'</tbody></table>'
 summary={}
 for factor in ['universe','entry_timeframe','trail','pyramid','risk','max_open_positions','preset']:
  groups={}
  for r in m['matrix']:
   v=str(r[factor]);groups.setdefault(v,[]).append(r)
  summary[factor]={v:dict(cases=len(rs),eligible=sum(r['eligible'] for r in rs),best_cagr=max(r['full']['cagr_pct'] for r in rs),best_eligible_cagr=max([r['full']['cagr_pct'] for r in rs if r['eligible']],default=None)) for v,rs in groups.items()}
 abl='<h2>مقایسهٔ عوامل رشد</h2><p>بهترین عضو هر گروه، اثر علّی مستقل عامل را اثبات نمی‌کند؛ جدول جفت‌های همسان در فایل ablation.json آمده است.</p><table><tr><th>عامل</th><th>مقدار</th><th>واجد شرایط / کل</th><th>بهترین CAGR واجد شرایط</th><th>بهترین CAGR بدون سقف DD</th></tr>'+''.join(f'<tr><td>{k}</td><td>{v}</td><td>{x["eligible"]} / {x["cases"]}</td><td>{fmt(x["best_eligible_cagr"])}</td><td>{fmt(x["best_cagr"])}</td></tr>' for k,g in summary.items() for v,x in g.items())+'</table>'
 paired=[]
 index={tuple((k,r[k]) for k in ['universe','preset','entry_timeframe','lookback','trail','risk','max_open_positions','pyramid']):r for r in m['matrix']}
 for r in m['matrix']:
  if not r['pyramid']:continue
  key=tuple((k,False if k=='pyramid' else r[k]) for k in ['universe','preset','entry_timeframe','lookback','trail','risk','max_open_positions','pyramid']);base=index[key]
  paired.append(dict(with_pyramid=r['id'],without_pyramid=base['id'],full_cagr_delta=r['full']['cagr_pct']-base['full']['cagr_pct'],full_dd_delta=r['full']['max_dd_pct']-base['full']['max_dd_pct'],adds=r['full']['pyramid_adds']))
 (OUT/'ablation.json').write_text(json.dumps(dict(group_summary=summary,pyramid_pairs=paired),indent=2))
 header='<tr><th rowspan="2">رتبه</th><th rowspan="2">تنظیمات</th><th rowspan="2">رده DD</th>'+''.join(f'<th colspan="5">{p}</th>' for p in ['کل ۵ سال','Train ۲۰۲۱–۲۰۲۴','اعتبارسنجی ۲۰۲۵–۲۰۲۶'])+'<th rowspan="2">ورود پایه</th><th rowspan="2">افزودن</th><th rowspan="2">کارمزد $</th><th rowspan="2">Funding $</th><th rowspan="2">میانگین مارجین ٪</th></tr><tr>'+('<th>CAGR ٪</th><th>بازده ٪</th><th>PF</th><th>DD ٪</th><th>سود خالص $</th>'*3)+'</tr>'
 controls=json.loads((OUT/'controls.json').read_text()) if (OUT/'controls.json').exists() else []
 refs='<h2>کنترل‌ها</h2><table><tr><th>نام</th><th>CAGR ٪</th><th>بازده ٪</th><th>PF</th><th>DD ٪</th><th>سود $</th></tr>'+''.join('<tr><td>'+html.escape(r['id'])+'</td>'+metrics(r['full'])+'</tr>' for r in controls)+'</table>'
 text=f'''<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>رشد CAGR پرتفوی Donchian</title><style>body{{font:14px/1.9 Tahoma,Arial;background:#101827;color:#e7edf7;margin:0;padding:26px}}h1,h2{{color:#71dccc}}section,article{{background:#1b283c;padding:20px;border-radius:12px;margin:18px 0}}.tiers{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}}table{{border-collapse:collapse;width:100%;font-size:12px}}td,th{{padding:10px;border:1px solid #34435b}}td{{direction:ltr}}th{{background:#253951}}.scroll{{overflow:auto}}select{{padding:10px;background:#22334b;color:white;margin:8px}}@media(max-width:750px){{.tiers{{display:block}}body{{padding:10px}}}}</style><h1>آزمون رشد CAGR — Donchian + Kumo</h1><p>دادهٔ واقعی Binance USD-M؛ ۵ اکتبر ۲۰۲۱ تا ۵ اکتبر ۲۰۲۶ (انتهای بازه غیرشامل). سرمایهٔ اولیهٔ هر اجرا $۱۰٬۰۰۰.</p><section><h2>انتخاب نهایی</h2>{winner}<p>مجموع {m['cases']} ترکیب و {m['cases']*3} اجرای دوره‌ای؛ {m['eligible_count']} واجد شرایط زیر ۳۵٪.</p></section><div class="tiers">{tiers}</div><section><h2>روش و محدودیت‌ها</h2><p>ورود ۴H با N10/N15 یا ۱H با N20/N40، فقط زیر رژیم آخرین کندل بستهٔ Kumo چهار‌ساعته. تریل کیجون در ماتریس، استاپ پله‌ای است؛ خروج فقط با کلوز کیجونِ نسخهٔ قبلی به‌عنوان کنترل جدا محاسبه شده است.</p><p>استاپ ATR2 سیگنال، رد فاصلهٔ کمتر از ۱٫۲٪ در سیگنال و ورود واقعی، کارمزد رفت‌وبرگشت ۰٫۱۲٪، لغزش نامطلوب ۲bps در هر ورود/خروج، Funding مشاهده‌شده تا سپتامبر ۲۰۲۶. برای ۱–۴ اکتبر ۲۰۲۶، Funding نامعلوم با هزینهٔ محافظه‌کارانهٔ ۰٫۰۱٪ در هر ۸ ساعت جایگزین شده است.</p><p>سقف مارجین کل ۶۰٪ و اهرم معادل ۵؛ اندازهٔ پوزیشن ریسک ثابت با ذخیرهٔ لغزش ۰٫۰۴٪. این ذخیره دوباره به هزینه‌ها اضافه نمی‌شود. توقف ورود با زیان خالص تحقق‌یافتهٔ ۲۴ ساعت به میزان ۲٪ equity.</p><p>افزودن فقط یک بار، با نصف ریسک، پس از ۲R و استاپ سودده با پوشش هزینه، روی شکست بعدی، با همان استاپ مشترک. قاعدهٔ REJECT برای واحد افزوده نیز برقرار است. اسلات به نماد تعلق دارد، نه تعداد واحدها.</p><p>شرط انتخاب: حداقل ۴۰ ورود پایه، سود مثبت Train و دورهٔ ۲۰۲۵–۲۰۲۶، و سقف DD در هر سه دوره. هر دوره مستقل از $۱۰٬۰۰۰ و بدون پوزیشن انتقالی شروع می‌شود؛ سودها جمع‌پذیر نیستند.</p><p>حذف BNB و این جست‌وجو با مشاهدهٔ عملکرد قبلی دورهٔ ۲۰۲۵–۲۰۲۶ انجام شده‌اند؛ این دوره دیگر OOS دست‌نخورده نیست. نتیجهٔ جدید، تضمین بازده آینده یا آمادگی معاملهٔ زنده نیست. مسیر درون‌دقیقه از OHLC تخمین زده می‌شود؛ دادهٔ مارک‌پرایس و لیکوئیدیشن بازسازی نشده‌اند.</p><p>۱۴٫۳۳٪ نسخهٔ قبلی، حداکثر مارجین در لحظهٔ ورود بود، نه میانگین. میانگین ساعتی مارجین همان نسخه حدود ۵٫۴۶٪ بود. گزارش حاضر میانگین هر دقیقه را جداگانه نشان می‌دهد.</p><p>هدف CAGR ۵۰–۱۰۰٪ صرفاً هدف پژوهش است و شرط‌ها پس از مشاهدهٔ نتایج تغییر نکرده‌اند.</p></section><p>کنترل‌های FIVE/BTC از موتور قبلی با سقف مارجین کل ۱۰۰٪، سقف نُوشنال هر واحد ۱۲۵٪ و بدون ذخیرهٔ اضافی لغزش در اندازه‌گیری ریسک استفاده می‌کنند؛ ماتریس جدید سقف ۶۰٪ و ذخیرهٔ ۰٫۰۴٪ دارد. هزینهٔ واقعی اجرا در هر دو یکسان است.</p>{refs}{breakdown}{abl}<section><h2>رتبه‌بندی همهٔ ترکیب‌ها بر اساس CAGR کل</h2><label>حداکثر DD در هر سه دوره<select id="tier"><option value="35">۳۵٪</option><option value="30">۳۰٪</option><option value="25">۲۵٪</option><option value="99">همه</option></select></label><label>سود هر دو دوره<select id="positive"><option value="1">مثبت</option><option value="0">همه</option></select></label><label>سبد<select id="universe"><option value="ALL">هر دو</option><option>FIVE</option><option>ALTS</option></select></label><p id="count"></p><div class="scroll"><table><thead>{header}</thead><tbody id="rows">{''.join(rows)}</tbody></table></div></section><script>function filter(){{let n=0;for(const r of document.querySelectorAll('#rows tr')){{const show=Number(r.dataset.tier)<=Number(document.getElementById('tier').value)&&(document.getElementById('positive').value==='0'||r.dataset.positive==='1')&&(document.getElementById('universe').value==='ALL'||r.dataset.universe===document.getElementById('universe').value);r.hidden=!show;if(show)n++;}}document.getElementById('count').textContent=n+' ترکیب نمایش داده می‌شود';}}for(const id of ['tier','positive','universe'])document.getElementById(id).addEventListener('change',filter);filter();</script></html>'''
 (OUT/'report_high_cagr_fa.html').write_text(text);print('REPORT',OUT/'report_high_cagr_fa.html')
if __name__=='__main__':main()
